ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn="everywhere"

fun isoToUnix(date) =
    if (date == null)
        null
    else
        (date as DateTime) as Number

fun generateEventId() =
    uuid()

---
{
    id: generateEventId(),

    (partner_user_id: payload.partnerUserId)
        if (payload.partnerUserId?),

    (timestamp: isoToUnix(payload.occurredAt))
        if (payload.occurredAt?),

    (event_type: payload.eventType)
        if (payload.eventType?),

    (event_data: {

        (address: {
            (country: payload.eventData.address.country)
                if (payload.eventData.address.country?)
        })
            if (payload.eventData.address?),

        (email: payload.eventData.email)
            if (payload.eventData.email?),

        (phone_number: payload.eventData.phoneNumber)
            if (payload.eventData.phoneNumber?),

        (name: payload.eventData.name)
            if (payload.eventData.name?),

        (products:
            payload.eventData.products map (product) -> {
                (code: product.code) if (product.code?),
                (name: product.name) if (product.name?),
                (starts: isoToUnix(product.starts)) if (product.starts?),
                (renews: isoToUnix(product.renews)) if (product.renews?),
                (expires: isoToUnix(product.expires)) if (product.expires?),
                (sub_id: product.subscriptionId) if (product.subscriptionId?),
                (trx_id: product.transactionId) if (product.transactionId?),
                (status: product.status) if (product.status?),
                (reason: product.reason) if (product.reason?)
            }
        )
            if (payload.eventData.products?),

        (products_terminated:
            payload.eventData.productsTerminated map (product) -> {
                (code: product.code) if (product.code?),
                (sub_id: product.subscriptionId) if (product.subscriptionId?)
            }
        )
            if (payload.eventData.productsTerminated?),

        (products_added:
            payload.eventData.productsAdded map (product) -> {
                (code: product.code) if (product.code?),
                (sub_id: product.subscriptionId) if (product.subscriptionId?),
                (starts: isoToUnix(product.starts)) if (product.starts?),
                (renews: isoToUnix(product.renews)) if (product.renews?),
                (trx_id: product.transactionId) if (product.transactionId?)
            }
        )
            if (payload.eventData.productsAdded?),

        (effective_date: isoToUnix(payload.eventData.effectiveDate))
            if (payload.eventData.effectiveDate?),

        (reason: payload.eventData.reason)
            if (payload.eventData.reason?),

        (details: payload.eventData.details)
            if (payload.eventData.details?)
    })
        if (payload.eventData?)
}

%dw 2.0
output application/json skipNullOn="everywhere"

---
{
  query: {
    insert: "MDM_TRAZABILIDAD_EVENTOS_THIRDPARTY",
    documents: [
      {
      	idEvento: vars.solicitudEvento.id,
        proveedor: "HBO",

        estado:
          if ((attributes.statusCode default 0) == 202)
            "EXITOSO"
          else
            "FALLIDO",

        solicitudesEventos: [
          vars.solicitudEvento
        ],

        respuestasEventos: [
          {
            idEvento: vars.solicitudEvento.id,
            event_type: vars.solicitudEvento.event_type,
            httpStatus: attributes.statusCode,
            fechaRespuesta:
              now() as String {
                format: "yyyy-MM-dd'T'HH:mm:ssXXX"
              }
          }
        ],

        notificacionesEventos: [],

        fechaCreacion:
          now() as String {
            format: "yyyy-MM-dd'T'HH:mm:ssXXX"
          },

        fechaActualizacion:
          now() as String {
            format: "yyyy-MM-dd'T'HH:mm:ssXXX"
          }
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
    query: {
        update: "MDM_CD_INVENTARIO",
        updates: [
            {
                q: {
                    Id_Cuenta_Servicio: vars.solicitudEvento.event_data.products[0].sub_id
                },
                u: {
                    "\$push": {
                        "Servicios.\$[servicio].Atributos": {
                            "\$each": [
                                {
                                    Atributo: "HBO_STATUS",
                                    Valor: "ACTIVE",
                                    Nuevo: true,
                                    Estado_Plataforma: 0
                                },
                                {
                                    Atributo: "HBO_ATTEMPS",
                                    Valor: "0",
                                    Nuevo: true,
                                    Estado_Plataforma: 0
                                }
                            ]
                        }
                    }
                },
                arrayFilters: [
                    {
                        "servicio.Clase_Servicio": "Broadband Service Class"
                    }
                ],
                multi: false,
                upsert: false
            }
        ]
    }
}

%dw 2.0
output application/json

fun unixToIso(timestamp) =
    (timestamp as DateTime) as String {
        format: "yyyy-MM-dd'T'HH:mm:ss'Z'"
    }

---
{
    (code: (payload.Code as String)) if (payload.Code != null),
    (message: payload.Message) if (payload.Message != null),
    data: {
        (products: payload.Result.products map (product) -> {
            (code: product.code) if (product.code != null),
            (name: product.name) if (product.name != null),
            (starts: unixToIso(product.starts)) if (product.starts != null),
            (renews: unixToIso(product.renews)) if (product.renews != null),
            (expires: unixToIso(product.expires)) if (product.expires != null),
            (status: product.status) if (product.status != null),
            (subscriptionId: product.sub_id) if (product.sub_id != null),
            (transactionId: product.trx_id) if (product.trx_id != null)
        }) if (payload.Result.products != null)
    }
}

%dw 2.0 output application/json
var product = payload.Result.products[0]
--- { partner_user_id: vars.partnerUserId, code: product.code, sub_id: product.sub_id, starts: product.starts }

logger.message:
#[%dw 2.0
output application/json
---
{
  "logMarker": "WBD_SIGNATURE_DEBUG_SYSTEM_INPUT",
  "layer": "PAPI",
  "request": {
    "method": attributes.method default "",
    "requestPath": attributes.requestPath default "",
    "headers": attributes.headers default {},
    "body": payload default {}
  }
}]

ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn="everywhere"

var notification = vars.notificacionEvento

---
{
  query: {
    update: "MDM_TRAZABILIDAD_EVENTOS_THIRDPARTY",
    updates: [
      {
        q: {
          "solicitudesEventos.partner_user_id": notification.partner_user_id,
          "solicitudesEventos.event_data.products.sub_id": notification.event_data.products[0].sub_id
        },

        u: {
          "\$push": {
            notificacionesEventos: notification
          },

          "\$set": {
            estado:
              if (notification.event_type == "error_notification")
                "FALLIDO"
              else
                "EXITOSO",

            fechaActualizacion:
              now() as String {
                format: "yyyy-MM-dd'T'HH:mm:ssXXX"
              }
          }
        },

        multi: false,
        upsert: false
      }
    ]
  }
}
